sourceFunctions.horse_race2:
title @a title {fallback:"Horse Race",translate:"mcp.horse_race",bold:1b,color:"dark_green",type:"translatable"}
playsound minecraft:entity.experience_orb.pickup master @a ~ ~ ~ 10 2 1
tellraw @a {fallback:"Race your horse along the track!",translate:"mcp.horse_race2.1",color:"dark_green",type:"translatable"}
scoreboard players set currentRule variables 0
scoreboard players set playingHorseRace variables 1
scoreboard objectives add checkpoint dummy
scoreboard objectives add hcheckpoint dummy
scoreboard objectives add lapscompleted dummy
scoreboard objectives add totalcheckpoints dummy {text:"Total Checkpoints",color:"dark_aqua",bold:1b}
scoreboard objectives add checkpoint_generic dummy {fallback:"Total Checkpoints",bold:1b,color:"dark_aqua",translate:"mcp.TotalCheckpoints",type:"translatable"}
scoreboard players set @a[scores={Player=1..}] checkpoint_generic 0
scoreboard objectives setdisplay sidebar checkpoint_generic
scoreboard objectives add totalcheckpoints2 dummy
scoreboard players set timeLeft variables 6000
gamerule naturalRegeneration true
team modify blue collisionRule never
team modify red collisionRule never
team modify green collisionRule never
team modify yellow collisionRule never
team add horse
summon minecraft:armor_stand 53 35 -1103 {Rotation:[180.0f,0.0f],Invulnerable:1b,PersistenceRequired:1b,Invisible:1b,Tags:["horse_spawn","horse_race"]}
summon minecraft:armor_stand 51 35 -1103 {Rotation:[180.0f,0.0f],Invulnerable:1b,PersistenceRequired:1b,Invisible:1b,Tags:["horse_spawn","horse_race"]}
