sourceFunctions.horse_race_generate:
execute in minecraft:the_nether run summon minecraft:armor_stand 55 39 -1133 {Silent:1b,Invisible:1b,PersistenceRequired:1b,Tags:["hr_path","hr_path1"]}
execute in minecraft:the_nether run summon minecraft:armor_stand 55 39 -1133 {Silent:1b,Invisible:1b,PersistenceRequired:1b,Tags:["hr_path","hr_path3"]}
execute in minecraft:the_nether run summon minecraft:armor_stand 55 39 -1133 {Silent:1b,Invisible:1b,PersistenceRequired:1b,Tags:["hr_path","hr_path2"]}

schedule function mcp:horse_race_generate2 2s

sourceFunctions.horse_race_rules:
execute as @a at @s run playsound minecraft:entity.experience_orb.pickup master @s ~ ~ ~ 10 2 1
scoreboard players add currentRule variables 1
execute if score playingHorseRace variables matches 1 if score currentRule variables matches ..2 as @a[scores={Player=1..}] at @s run tp @s ~ ~ ~ 180 0

execute if score currentRule variables matches 2 run tellraw @a {fallback:"Go through the course while jumping over the obstacles.",translate:"mcp.horse_race_rules.1",color:"dark_aqua",type:"translatable"}
execute if score currentRule variables matches 3 run tellraw @a {fallback:"Hold down jump key (spacebar by default) to charge up your jump. Look at xp bar to see how much your jump is charged up.",translate:"mcp.horse_race_rules.2",color:"dark_green",type:"translatable"}
execute if score currentRule variables matches 4 run tellraw @a {fallback:"Run over gold blocks with your horse to reach checkpoints.",translate:"mcp.horse_race_rules.3",color:"dark_aqua",type:"translatable"}
execute if score currentRule variables matches 5 run tellraw @a {fallback:"If your horses catches on fire, then you reset to your last checkpoint.",translate:"mcp.horse_race_rules.4",color:"dark_green",type:"translatable"}
execute if score currentRule variables matches 6 run tellraw @a {fallback:"You can drop your flag at any time to reset to your checkpoint.",translate:"mcp.horse_race_rules.5",color:"dark_aqua",type:"translatable"}
execute if score currentRule variables matches 7 run tellraw @a {fallback:"Be the first to complete two laps to win!",translate:"mcp.horse_race_rules.6",color:"dark_green",type:"translatable"}
execute if score currentRule variables matches 8 run function mcp:ready_up_tellraw
execute if score currentRule variables matches 1..7 run schedule function mcp:horse_race_rules 3s

sourceFunctions.checkpoint2:
scoreboard players set @a[scores={Player=1..}] checkpoint_generic 0
execute if score minigame variables matches 401 as @a run scoreboard players operation @s checkpoint = @s max_blocks_fallen
execute if score minigame variables matches 405 as @a run scoreboard players operation @s checkpoint = @s lapscompleted
